function calculateReward(response, correctAnswer):
# Check if answer is correct
if extractNumber(response) == correctAnswer:
reward = +1.0
# Bonus for clean format
if response == str(correctAnswer):
reward += 0.0 # Already perfect
else:
reward -= 0.2 # Not clean
# Bonus for showing reasoning
if hasReasoningSteps(response):
reward += 0.2
else:
reward = -1.0 # Wrong!
return reward
